findings.codeql_raw_query:
/**
 * @name Path traversal via zipfile extraction in openpyxl
 * @description Detects uses of zipfile.ZipFile.extract or extractall that may allow writing files outside the target directory if given attacker-controlled archives.
 * @kind path-problem
 * @problem.severity error
 * @id py/openpyxl-zip-path-traversal
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module ZipTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Any remote input flowing into openpyxl.load_workbook or reader functions
    exists(API::CallNode c |
      source = c and
      (
        c = API::moduleImport("openpyxl").getMember("load_workbook").getACall() or
        c = API::moduleImport("openpyxl.reader.excel").getMember("load_workbook").getACall()
      ) and
      source instanceof RemoteFlowSource
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Calls to ZipFile.extract or extractall
    exists(API::CallNode c |
      sink = c and
      c = API::moduleImport("zipfile").getMember("ZipFile!").getMember(["extract", "extractall"]).getACall()
    )
  }
}

module ZipTraversalFlow = TaintTracking::Global<ZipTraversalConfig>;
import ZipTraversalFlow::PathGraph

from ZipTraversalFlow::PathNode source, ZipTraversalFlow::PathNode sink
where ZipTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled archive data reaches zip extraction here, which may allow path traversal (CWE-22).", source.getNode(), "user-controlled archive"
